-- More leg exercises in machines for the Strength Hub: lying leg curl, hip thrust, hip abduction and adduction,
-- glute kickback, standing and seated calf raise, calf raise in the leg press, single-leg leg press, belt squat and
-- Smith machine split squat.
-- Generated by scripts/leg-machines-migration.mjs from src/strength-catalog-legs.js; edit those, not the .sql.
-- Only new exercise ids are added. Saved workouts, XP, ranks and baselines are unchanged.
begin;
alter function public.arc_strength_meta(text) rename to arc_strength_meta_v33;
create function public.arc_strength_meta(id text) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select coalesce((select value from jsonb_array_elements('[{"id":"lying-leg-curl","name":"Liggande lårcurl","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"lying-leg-curl","thresholds":[0.15,0.3,0.45,0.6,0.75,0.9],"cue":"Ligg på mage med knäna precis nedanför dynan och rullen strax ovanför hälarna. Böj benen lugnt och håll höften mot dynan.","unit":"kg","aliases":"Lying Leg Curl hamstrings baksida lår"},{"id":"hip-thrust-machine","name":"Höftlyft i maskin","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"hip-thrust","thresholds":[0.5,0.8,1.1,1.5,1.9,2.3],"cue":"Övre delen av ryggen mot dynan och fötterna i golvet. Pressa upp höften med sätet tills kroppen är rak från axlar till knän, utan att svanka.","unit":"kg","aliases":"Hip Thrust Machine glutes säte rumpa"},{"id":"hip-abduction","name":"Abduktor (höft utåt)","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"hip-abduction","thresholds":[0.2,0.35,0.5,0.65,0.8,1],"cue":"Sitt med ryggen mot stödet och dynorna mot utsidan av knäna. För isär benen med sätet och låt dem gå tillbaka långsamt.","unit":"kg","aliases":"Abductor Abduktor Hip Abduction Machine höftabduktion glutes säte utsida lår"},{"id":"hip-adduction","name":"Adduktor (höft inåt)","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"hip-adduction","thresholds":[0.2,0.35,0.5,0.65,0.8,1],"cue":"Sitt med ryggen mot stödet och dynorna mot insidan av knäna. Börja i ett bekvämt omfång och pressa ihop benen kontrollerat.","unit":"kg","aliases":"Adductor Adduktor Hip Adduction Machine höftadduktion adduktorer insida lår"},{"id":"glute-kickback","name":"Glute kickback i maskin","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"glute-kickback","thresholds":[0.1,0.2,0.3,0.45,0.6,0.75],"cue":"Stöd överkroppen mot dynan och spänn bålen. Pressa benet bakåt med sätet utan att svanka. Logga vikten för ett ben.","unit":"kg","aliases":"Glute Kickback Machine säte rumpa"},{"id":"standing-calf","name":"Stående vadpress i maskin","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"calf-raise","thresholds":[0.4,0.7,1,1.3,1.6,2],"cue":"Främre delen av foten på kanten och raka knän. Sänk hälarna långsamt, pausa och res dig så högt du kan.","unit":"kg","aliases":"Standing Calf Raise vader calves"},{"id":"seated-calf","name":"Sittande vadpress","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"seated-calf","thresholds":[0.2,0.4,0.6,0.8,1,1.2],"cue":"Sitt med dynan över låren och främre delen av foten på plattan. Sänk hälarna långsamt och pressa upp så högt du kan.","unit":"kg","aliases":"Seated Calf Raise vader calves"},{"id":"leg-press-calf","name":"Vadpress i benpress","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"leg-press-calf","thresholds":[0.5,1,1.5,2,2.5,3],"cue":"Raka men inte låsta knän och främre delen av foten mot plattans nederkant. Pressa med vaderna och håll säkerhetsspärrarna nära.","unit":"kg","aliases":"Leg Press Calf Raise vader calves"},{"id":"single-leg-press","name":"Benpress med ett ben","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"leg-press","thresholds":[0.25,0.5,0.75,1,1.25,1.5],"cue":"Ett ben mitt på plattan och bäckenet mot dynan. Sänk kontrollerat och pressa utan att knät faller inåt. Logga vikten per ben.","unit":"kg","aliases":"Single-Leg Leg Press"},{"id":"belt-squat","name":"Belt squat","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"squat","thresholds":[0.4,0.7,1,1.3,1.6,2],"cue":"Bältet runt höften och händerna på handtagen. Sätt dig ned med rak överkropp och res dig genom hela foten. Ryggen slipper axellasten.","unit":"kg","aliases":"Belt Squat knäböj"},{"id":"smith-split-squat","name":"Utfallsböj i smithmaskin","muscle":"Ben","equipment":"Maskin","family":"legs","pose":"lunge","thresholds":[0.2,0.4,0.6,0.8,1,1.2],"cue":"Stången på övre ryggen och ett långt steg isär. Sänk bakre knät mot golvet och pressa upp med främre benet. Logga per ben.","unit":"kg","aliases":"Smith Machine Split Squat utfall"}]'::jsonb) where value->>'id'=id),public.arc_strength_meta_v33(id))
$$;
revoke all on function public.arc_strength_meta_v33(text) from public,anon,authenticated;
create or replace function public.training_expansion_ready() returns integer language sql stable as $$select 34$$;
insert into public.schema_migrations(name) values('034_leg_machines') on conflict do nothing;
notify pgrst,'reload schema';
commit;
